public class CodeBrowserPlugin : AbstractCodeBrowserPlugin<CodeViewerProvider>, PluginWithTransientState<CodeBrowserTransientState> {

	public CodeBrowserPlugin(PluginTool tool) : base(tool)
    {

		registerServiceProvided(typeof(FieldMouseHandlerService),
			connectedProvider.getFieldNavigator());

		// sets the primary code viewer window as the default component to get focus
		tool.setDefaultComponent(connectedProvider);

		// sets the primary code viewer window as the default context provider for actions 
		// that use the specified context types. 
		tool.registerDefaultContextProvider(typeof(ProgramActionContext), connectedProvider);
		tool.registerDefaultContextProvider(typeof(NavigatableActionContext), connectedProvider);
		tool.registerDefaultContextProvider(typeof(CodeViewerActionContext), connectedProvider);
		tool.registerDefaultContextProvider(typeof(ListingActionContext), connectedProvider);
	}

	/* @Override */
	protected void dispose() {
		tool.unregisterDefaultContextProvider(typeof(ProgramActionContext), connectedProvider);
		tool.unregisterDefaultContextProvider(typeof(NavigatableActionContext), connectedProvider);
		tool.unregisterDefaultContextProvider(typeof(CodeViewerActionContext), connectedProvider);
		tool.unregisterDefaultContextProvider(typeof(ListingActionContext), connectedProvider);
		base.dispose();
	}

	/* @Override */
	protected CodeViewerProvider createProvider(FormatManager formatManager, bool isConnected) {
		return new CodeViewerProvider(this, formatManager, isConnected);
	}

	/* @Override */
	public void broadcastHighlightChanged(CodeViewerProvider provider, ProgramSelection highlight) {
		if (provider == connectedProvider) {
			tool.firePluginEvent(new ProgramHighlightPluginEvent(getName(), highlight,
				connectedProvider.getProgram()));
		}
	}

	/* @Override */
	public void broadcastLocationChanged(CodeViewerProvider provider, ProgramLocation location) {
		if (provider == connectedProvider) {
			tool.firePluginEvent(new ProgramLocationPluginEvent(getName(), location,
				connectedProvider.getProgram()));
		}
	}

	/* @Override */
	public void processEvent(PluginEvent @event) {
		if (@event is ProgramClosedPluginEvent) {
			Program program = ((ProgramClosedPluginEvent) @event).getProgram();
			programClosed(program);
			return;
		}
		if (@event is ProgramActivatedPluginEvent) {
			if (currentProgram != null) {
				currentProgram.removeListener(this);
			}
			ProgramActivatedPluginEvent evt = (ProgramActivatedPluginEvent) @event;
			connectedProvider.clearMarkers(currentProgram); // do this before changing the program

			currentProgram = evt.getActiveProgram();
			if (currentProgram != null) {
				currentProgram.addListener(this);
				currentView = currentProgram.getMemory();
			}
			else {
				currentView = new AddressSet();
			}

			connectedProvider.doSetProgram(currentProgram);

			connectedProvider.updateHighlightProvider();
			updateBackgroundColorModel(connectedProvider);
			setConnectedProviderHighlight(new FieldSelection());
			setConnectedProviderSelection(new ProgramSelection());
		}
		else if (@event is ProgramLocationPluginEvent) {
			ProgramLocationPluginEvent evt = (ProgramLocationPluginEvent) @event;
			ProgramLocation location = evt.getLocation();
			if (!connectedProvider.setLocation(location)) {
				if (viewManager != null) {
					AddressSetView updatedView = viewManager.addToView(location);
					setView(updatedView);
					ListingPanel lp = connectedProvider.getListingPanel();
					lp.goTo(location, true);
				}
			}
		}
		else if (@event is ProgramSelectionPluginEvent) {
			ProgramSelectionPluginEvent evt = (ProgramSelectionPluginEvent) @event;
			setConnectedProviderSelection(evt.getSelection());
		}
		else if (@event is ProgramHighlightPluginEvent) {
			ProgramHighlightPluginEvent evt = (ProgramHighlightPluginEvent) @event;
			if (evt.getProgram() == currentProgram) {
				connectedProvider.setHighlight(evt.getHighlight());
			}
		}
		else if (@event is ViewChangedPluginEvent) {
			AddressSet view = ((ViewChangedPluginEvent) @event).getView();
			setView(view);
		}
	}

	protected void programClosed(Program closedProgram) {
		Iterator<CodeViewerProvider> iterator = disconnectedProviders.iterator();
		while (_iterator.hasNext()) {
			CodeViewerProvider provider = _iterator.next();
			if (provider.getProgram() == closedProgram) {
				_iterator.remove();
				removeProvider(provider);
			}
		}
	}

	record CodeBrowserTransientState(ViewerPosition position, ProgramLocation location,
			ProgramSelection highlight, ProgramSelection selection, AddressSetView view) {}

	/* @Override */
	public CodeBrowserTransientState getTransientState() {
		FieldPanel fieldPanel = connectedProvider.getListingPanel().getFieldPanel();
		return new CodeBrowserTransientState(fieldPanel.getViewerPosition(),
			connectedProvider.getLocation(), connectedProvider.getHighlight(),
			connectedProvider.getSelection(), currentView);
	}

	/* @Override */
	public void restoreTransientState(CodeBrowserTransientState state) {
		setView(state.view);
		if (state.location != null) {
			connectedProvider.setLocation(state.location);
		}
		connectedProvider.setHighlight(state.highlight);
		if (state.selection != null) {
			connectedProvider.setSelection(state.selection);
		}
		ViewerPosition vp = state.position;
		if (vp != null) {
			FieldPanel fieldPanel = connectedProvider.getListingPanel().getFieldPanel();
			fieldPanel.setViewerPosition(vp.getIndex(), vp.getXOffset(), vp.getYOffset());
		}
	}

	/* @Override */
	public void writeDataState(SaveState saveState) {
		if (connectedProvider != null) {
			connectedProvider.writeDataState(saveState);
		}
		saveState.putInt("Num Disconnected", disconnectedProviders.size());
		int i = 0;
		foreach (CodeViewerProvider provider in disconnectedProviders) {
			SaveState providerSaveState = new SaveState();
			DomainFile df = provider.getProgram().getDomainFile();
			if (df.getParent() == null) {
				continue; // not contained within project
			}
			string programPathname = df.getPathname();
			providerSaveState.putString("Program Path", programPathname);
			provider.writeDataState(providerSaveState);
			string elementName = "Provider" + i;
			saveState.putXmlElement(elementName, providerSaveState.saveToXml());
			i++;
		}
		FieldSelection highlight =
			connectedProvider.getListingPanel().getFieldPanel().getHighlight();
		highlight.save(saveState);
	}

	/* @Override */
	public void readDataState(SaveState saveState) {
		ProgramManager programManagerService = tool.getService(typeof(ProgramManager));

		if (connectedProvider != null) {
			connectedProvider.readDataState(saveState);
		}
		int numDisconnected = saveState.getInt("Num Disconnected", 0);
		for (int i = 0; i < numDisconnected; i++) {
			Element xmlElement = saveState.getXmlElement("Provider" + i);
			SaveState providerSaveState = new SaveState(xmlElement);
			string programPath = providerSaveState.getString("Program Path", "");
			DomainFile file = tool.getProject().getProjectData().getFile(programPath);
			if (file == null) {
				continue;
			}
			Program program = programManagerService.openProgram(file);
			if (program != null) {
				CodeViewerProvider provider = createNewDisconnectedProvider();
				provider.doSetProgram(program);
				provider.readDataState(providerSaveState);
			}
		}

		FieldSelection highlight = new FieldSelection();
		highlight.load(saveState);
		if (!highlight.isEmpty()) {
			setConnectedProviderHighlight(highlight);
		}
	}

	/* @Override */
	public void writeConfigState(SaveState saveState) {
		base.writeConfigState(saveState);
		formatMgr.saveState(saveState);
		connectedProvider.saveState(saveState);
	}

	/* @Override */
	public void readConfigState(SaveState saveState) {
		base.readConfigState(saveState);
		formatMgr.readState(saveState);
		connectedProvider.readState(saveState);
	}

	/* @Override */
	public ViewManagerService getViewManager(CodeViewerProvider codeViewerProvider) {
		if (codeViewerProvider == connectedProvider) {
			return viewManager;
		}
		return null;
	}
}
